 "content": "def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_run(values):
        inds = [i for i, value in enumerate(values) if value != bg]
        if not inds or inds != list(range(inds[0], inds[-1] + 1)):
            return None
        colors = {values[i] for i in inds}
        if len(colors) != 1:
            return None
        return inds[0], inds[-1] + 1, values[inds[0]]

    def matched(a, b):
        return a and b and a[2] == b[2] and a[1] - a[0] == b[1] - b[0]

    top = edge_run(grid[0])
    bottom = edge_run(grid[-1])
    if matched(top, bottom):
        seeds = [(r, c, grid[r][c]) for r in range(1, h - 1)
                 for c in range(1, w - 1) if grid[r][c] != bg]
        for r, c, color in seeds:
            if top[0] <= c < top[1]:
                mate = bottom[0] + c - top[0]
                source_rows = range(1, r)
            elif bottom[0] <= c < bottom[1]:
                mate = top[0] + c - bottom[0]
                source_rows = range(r + 1, h - 1)
            else:
                continue
            for rr in source_rows:
                if out[rr][c] == bg:
                    out[rr][c] = color
            out[r][c] = 4
            for rr in range(h):
                if out[rr][mate] == bg:
                    out[rr][mate] = color
        return out

    left = edge_run([grid[r][0] for r in range(h)])
    right = edge_run([grid[r][-1] for r in range(h)])
    if matched(left, right):
        seeds = [(r, c, grid[r][c]) for r in range(1, h - 1)
                 for c in range(1, w - 1) if grid[r][c] != bg]
        for r, c, color in seeds:
            if left[0] <= r < left[1]:
                mate = right[0] + r - left[0]
                source_cols = range(1, c)
            elif right[0] <= r < right[1]:
                mate = left[0] + r - right[0]
                source_cols = range(c + 1, w - 1)
            else:
                continue
            for cc in source_cols:
                if out[r][cc] == bg:
                    out[r][cc] = color
            out[r][c] = 4
            for cc in range(w):
                if out[mate][cc] == bg:
                    out[mate][cc] = color
        return out
    return out
